-- ASTRA usage counters (Cloudflare D1). Idempotent: safe to run on every deploy.
CREATE TABLE IF NOT EXISTS usage (uid TEXT NOT NULL, day TEXT NOT NULL, mode TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (uid, day, mode));
CREATE TABLE IF NOT EXISTS user_cost (uid TEXT NOT NULL, day TEXT NOT NULL, in_tok INTEGER NOT NULL DEFAULT 0, out_tok INTEGER NOT NULL DEFAULT 0, usd REAL NOT NULL DEFAULT 0, PRIMARY KEY (uid, day));
CREATE TABLE IF NOT EXISTS spend (day TEXT PRIMARY KEY, usd REAL NOT NULL DEFAULT 0, calls INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS events (uid TEXT NOT NULL, at TEXT NOT NULL, day TEXT NOT NULL, name TEXT NOT NULL, props TEXT NOT NULL DEFAULT '{}', app TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS events_uid_day ON events (uid, day);
CREATE INDEX IF NOT EXISTS events_name_day ON events (name, day);
CREATE TABLE IF NOT EXISTS feedback (uid TEXT NOT NULL, at TEXT NOT NULL, text TEXT NOT NULL, app TEXT NOT NULL DEFAULT '');
